	/**
	* @file audio-track-menu-item.js
	*/
	/** @import Player from '../../player' */
	/**
	* An {@link AudioTrack} {@link MenuItem}
	*
	* @extends MenuItem
	*/
	var AudioTrackMenuItem = class extends MenuItem {
		/**
		* Creates an instance of this class.
		*
		* @param {Player} player
		*        The `Player` that this class should be attached to.
		*
		* @param {Object} [options]
		*        The key/value store of player options.
		*/
		constructor(player, options) {
			const track = options.track;
			const tracks = player.audioTracks();
			options.label = track.label || track.language || "Unknown";
			options.selected = track.enabled;
			super(player, options);
			this.track = track;
			this.addClass(`vjs-${track.kind}-menu-item`);
			const changeHandler = (...args) => {
				this.handleTracksChange.apply(this, args);
			};
			tracks.addEventListener("change", changeHandler);
			this.on("dispose", () => {
				tracks.removeEventListener("change", changeHandler);
			});
		}
		createEl(type, props, attrs) {
			const el = super.createEl(type, props, attrs);
			const parentSpan = el.querySelector(".vjs-menu-item-text");
			if (["main-desc", "descriptions"].indexOf(this.options_.track.kind) >= 0) {
				parentSpan.appendChild(createEl("span", { className: "vjs-icon-placeholder" }, { "aria-hidden": true }));
				parentSpan.appendChild(createEl("span", {
					className: "vjs-control-text",
					textContent: " " + this.localize("Descriptions")
				}));
			}
			return el;
		}
		/**
		* This gets called when an `AudioTrackMenuItem is "clicked". See {@link ClickableComponent}
		* for more detailed information on what a click can be.
		*
		* @param {Event} [event]
		*        The `keydown`, `tap`, or `click` event that caused this function to be
		*        called.
		*
		* @listens tap
		* @listens click
		*/
		handleClick(event) {
			super.handleClick(event);
			this.track.enabled = true;
			if (this.player_.tech_.featuresNativeAudioTracks) {
				const tracks = this.player_.audioTracks();
				for (let i = 0; i < tracks.length; i++) {
					const track = tracks[i];
					if (track === this.track) continue;
					track.enabled = track === this.track;
				}
			}
		}
		/**
		* Handle any {@link AudioTrack} change.
		*
		* @param {Event} [event]
		*        The {@link AudioTrackList#change} event that caused this to run.
		*
		* @listens AudioTrackList#change
		*/
		handleTracksChange(event) {
			this.selected(this.track.enabled);
		}
	};
	Component.registerComponent("AudioTrackMenuItem", AudioTrackMenuItem);
	/**
	* @file audio-track-button.js
	*/
	/**
	* The base class for buttons that toggle specific {@link AudioTrack} types.
	*
	* @extends TrackButton
	*/
	var AudioTrackButton = class extends TrackButton {
		/**
		* Creates an instance of this class.
		*
		* @param {Player} player
		*        The `Player` that this class should be attached to.
		*
		* @param {Object} [options={}]
		*        The key/value store of player options.
		*/
		constructor(player, options = {}) {
			options.tracks = player.audioTracks();
			super(player, options);
			this.setIcon("audio");
		}
		/**
		* Builds the default DOM `className`.
		*
		* @return {string}
		*         The DOM `className` for this object.
		*/
		buildCSSClass() {
			return `vjs-audio-button ${super.buildCSSClass()}`;
		}
		buildWrapperCSSClass() {
			return `vjs-audio-button ${super.buildWrapperCSSClass()}`;
		}
		/**
		* Create a menu item for each audio track
		*
		* @param {AudioTrackMenuItem[]} [items=[]]
		*        An array of existing menu items to use.
		*
		* @return {AudioTrackMenuItem[]}
		*         An array of menu items
		*/
		createItems(items = []) {
			this.hideThreshold_ = 1;
			const tracks = this.player_.audioTracks();
			for (let i = 0; i < tracks.length; i++) {
				const track = tracks[i];
				items.push(new AudioTrackMenuItem(this.player_, {
					track,
					selectable: true,
					multiSelectable: false
				}));
			}
			return items;
		}
	};
	/**
	* The text that should display over the `AudioTrackButton`s controls. Added for localization.
	*
	* @type {string}
	* @protected
	*/
	AudioTrackButton.prototype.controlText_ = "Audio Track";
	Component.registerComponent("AudioTrackButton", AudioTrackButton);
	/**
	* @file playback-rate-menu-item.js
	*/
	/** @import Player from '../../player' */
	/**
	* The specific menu item type for selecting a playback rate.
	*
	* @extends MenuItem
	*/
	var PlaybackRateMenuItem = class extends MenuItem {
		/**
		* Creates an instance of this class.
		*
		* @param {Player} player
		*        The `Player` that this class should be attached to.
		*
		* @param {Object} [options]
		*        The key/value store of player options.
		*/
		constructor(player, options) {
			const label = options.rate;
			const rate = parseFloat(label, 10);
			options.label = label;
			options.selected = rate === player.playbackRate();
			options.selectable = true;
			options.multiSelectable = false;
			super(player, options);
			this.label = label;
			this.rate = rate;
			this.on(player, "ratechange", (e) => this.update(e));
		}
		/**
		* This gets called when an `PlaybackRateMenuItem` is "clicked". See
		* {@link ClickableComponent} for more detailed information on what a click can be.
		*
		* @param {Event} [event]
		*        The `keydown`, `tap`, or `click` event that caused this function to be
		*        called.
		*
		* @listens tap
		* @listens click
		*/
		handleClick(event) {
			super.handleClick();
			this.player().playbackRate(this.rate);
		}
		/**
		* Update the PlaybackRateMenuItem when the playbackrate changes.
		*
		* @param {Event} [event]
		*        The `ratechange` event that caused this function to run.
		*
		* @listens Player#ratechange
		*/
		update(event) {
			this.selected(this.player().playbackRate() === this.rate);
		}
	};
	/**
	* The text that should display over the `PlaybackRateMenuItem`s controls. Added for localization.
	*
	* @type {string}
	* @private
	*/
	PlaybackRateMenuItem.prototype.contentElType = "button";
	Component.registerComponent("PlaybackRateMenuItem", PlaybackRateMenuItem);
	/**
	* @file playback-rate-menu-button.js
	*/
	/** @import Player from '../../player' */
	/**
	* The component for controlling the playback rate.
	*
	* @extends MenuButton
	*/
	var PlaybackRateMenuButton = class extends MenuButton {
		/**
		* Creates an instance of this class.
		*
		* @param {Player} player
		*        The `Player` that this class should be attached to.
		*
		* @param {Object} [options]
		*        The key/value store of player options.
		*/
		constructor(player, options) {
			super(player, options);
			this.menuButton_.el_.setAttribute("aria-describedby", this.labelElId_);
			this.updateVisibility();
			this.updateLabel();
			this.on(player, "loadstart", (e) => this.updateVisibility(e));
			this.on(player, "ratechange", (e) => this.updateLabel(e));
			this.on(player, "playbackrateschange", (e) => this.handlePlaybackRateschange(e));
		}
		/**
		* Create the `Component`'s DOM element
		*
		* @return {Element}
		*         The element that was created.
		*/
		createEl() {
			const el = super.createEl();
			this.labelElId_ = "vjs-playback-rate-value-label-" + this.id_;
			this.labelEl_ = createEl("div", {
				className: "vjs-playback-rate-value",
				id: this.labelElId_,
				textContent: "1x"
			});
			el.appendChild(this.labelEl_);
			return el;
		}
		dispose() {
			this.labelEl_ = null;
			super.dispose();
		}
		/**
		* Builds the default DOM `className`.
		*
		* @return {string}
		*         The DOM `className` for this object.
		*/
		buildCSSClass() {
			return `vjs-playback-rate ${super.buildCSSClass()}`;
		}
		buildWrapperCSSClass() {
			return `vjs-playback-rate ${super.buildWrapperCSSClass()}`;
		}
		/**
		* Create the list of menu items. Specific to each subclass.
		*
		*/
		createItems() {
			const rates = this.playbackRates();
			const items = [];
			for (let i = rates.length - 1; i >= 0; i--) items.push(new PlaybackRateMenuItem(this.player(), { rate: rates[i] + "x" }));
			return items;
		}
		/**
		* On playbackrateschange, update the menu to account for the new items.
		*
		* @listens Player#playbackrateschange
		*/
		handlePlaybackRateschange(event) {
			this.update();
		}
		/**
		* Get possible playback rates
		*
		* @return {Array}
		*         All possible playback rates
		*/
		playbackRates() {
			const player = this.player();
			return player.playbackRates && player.playbackRates() || [];
		}
		/**
		* Get whether playback rates is supported by the tech
		* and an array of playback rates exists
		*
		* @return {boolean}
		*         Whether changing playback rate is supported
		*/
		playbackRateSupported() {
			return this.player().tech_ && this.player().tech_.featuresPlaybackRate && this.playbackRates() && this.playbackRates().length > 0;
		}
		/**
		* Hide playback rate controls when they're no playback rate options to select
		*
		* @param {Event} [event]
		*        The event that caused this function to run.
		*
		* @listens Player#loadstart
		*/
		updateVisibility(event) {
			if (this.playbackRateSupported()) this.removeClass("vjs-hidden");
			else this.addClass("vjs-hidden");
		}
		/**
		* Update button label when rate changed
		*
		* @param {Event} [event]
		*        The event that caused this function to run.
		*
		* @listens Player#ratechange
		*/
		updateLabel(event) {
			if (this.playbackRateSupported()) this.labelEl_.textContent = this.player().playbackRate() + "x";
		}
	};
	/**
	* The text that should display over the `PlaybackRateMenuButton`s controls.
	*
	* Added for localization.
	*
	* @type {string}
	* @protected
	*/
	PlaybackRateMenuButton.prototype.controlText_ = "Playback Rate";
	Component.registerComponent("PlaybackRateMenuButton", PlaybackRateMenuButton);
